mapper.select:
SELECT i.expense_type, i.city, i.expense_date, SUM(i.amount) AS amount
FROM biz_expense_claim c
JOIN biz_expense_item i ON i.claim_id = c.id AND i.tenant_id = c.tenant_id
WHERE c.tenant_id = #{tenantId} AND c.user_id = #{userId}
  AND c.deleted = 0 AND c.status IN ('PENDING', 'APPROVED', 'PAID')
  AND c.id != #{excludeClaimId}
  AND i.expense_date >= #{from} AND i.expense_date < #{until}
  AND i.expense_type IN
  #{type}
GROUP BY i.expense_type, i.city, i.expense_date
